    "question": "森林が有する災害防止機能に関する記述A～Dのうち、妥当なもののみを挙げているのはどれか。\n\nA. 森林が有する表層崩壊防止機能は、主に樹木の根系によって発揮されている。この機能は、崩壊時に表層土が斜面下方に向かって変位する際に、表層土中の根も引っ張られ、根に生じる引っ張り応力が崩壊すべり面の土のせん断抵抗力を補強することで発揮されると考えられている。\nB. 土石流が森林内に流入した場合、森林が土石流の流下エネルギーを減少させることで停止を促進する。一般に、土石流は渓床勾配が20°程度から堆積し始め、10°程度で自然と停止するため、10°より緩い斜面の森林には土石流を停止させる効果はない。\nC. 海岸防災林は、飛砂防備に加えて、津波による漂流物の捕捉等による被害軽減効果はあるが、津波の内陸への到達時間を遅延させる効果はない。また、海岸防災林は、平成23（2011）年の東北地方太平洋沖地震に伴う津波により、その多くが流失したため、現在では津波対策としては位置付けられていない。\nD. 荒廃した森林が回復・成長することで、過去の豪雨と同等の総降雨量でも山地災害の発生箇所数が大幅に減少する事例が確認されている。一方で、近年の気候変動に伴う大雨の激化等により、平成29（2017）年7月九州北部豪雨では大規模な流木災害が発生するなど、流木災害が激甚化している。",
