    "question": "多国間条約とそれに関連した我が国の政策に関する記述として最も妥当なのはどれか。\n\n*1 世界の文化遺産及び自然遺産の保護に関する条約\n*2 生物多様性条約第15回締約国会議\n*3 Intergovernmental Panel on Climate Change（気候変動に関する政府間パネル）が2023年に公表した第6次評価報告書の統合報告書\n*4 絶滅のおそれのある野生動植物の種の国際取引に関する条約\n*5 特に水鳥の生息地として国際的に重要な湿地に関する条約",
