      "エ": "ワシントン条約*4は、野生動植物種の絶滅を防止するため、生態系の多様性、種間の多様性、種内の多様性の保全を図ることを目的としている。同条約では、規制が必要と考えられる野生動植物種を附属書にリストアップしており、附属書に掲載された種は、それぞれの必要性に応じて、捕獲・採取、飼育・栽培の規制が行われている。",
      "オ": "ラムサール条約*5は、水鳥の生息地として国際的に重要な湿地及びそこに生息・生育する動植物の保全、ワイズユース（賢明な利用）並びに、保全と賢明な利用を促進する交流・学習の三つを基盤の考えとしている。締約国は、自国の領域内にある国際的に重要な湿地を一箇所以上登録することとされており、我が国は、同条約加入の際に釧路湿原を登録した。"
