    "difficulty": 3,
    "question": "我が国の森林・林業に関係する法制度に関する記述として最も妥当なのはどれか。",
    "choices": {
      "ア": "明治時代には、木材が産業用燃料や建設資材など様々な用途に使われるようになったことを受けて、国内各地で森林伐採が盛んに行われたため、森林の荒廃が深刻化して、災害が頻発した。明治30（1897）年には、森林の保全や保続を図るため、防災機能を発揮させる森林などを保全する森林保険制度と、過伐・乱伐を防止する森林組合制度を柱とする森林法が成立した。",
      "イ": "旺盛な木材需要に対応した国産材の供給を図ることができるよう、昭和39（1964）年に、木材の安定供給の確保に関する特別措置法が制定された。同法の下では、パルプ用材としての需要を見込んで、針葉樹林の伐採跡地に広葉樹を植栽する拡大造林によって林業的利用に供される森林を拡大し、森林生産力の増強を図るとともに、機械化の推進などによって生産性の向上を図ることとされた。",
      "ウ": "平成3（1991）年のバブル景気崩壊後の木材需要の減少などにより、木材価格が長期的に低迷して林業生産活動が停滞した。しかし、国民の木材等生産機能の発揮に対するニーズは依然として高かったことから、平成13（2001）年に森林・林業基本法が制定され、森林の多面的機能の発揮を図る政策から、林業経営を一層効率化するための政策へ転換することとされた。",
      "エ": "平成23（2011）年には、森林・林業基本法の改正により、面的なまとまりのある森林において、森林の施業を自ら行う意欲のある森林所有者又は森林の施業の委託を受けた者が、継続的に森林の施業・保護を実施できるようにするための森林施業計画制度が創設された。同計画の認定を受けた者は、税制上の特例措置などを受けることができる。",
      "オ": "平成31（2019）年4月に施行された森林経営管理法により、手入れの行き届いていない森林について、市町村が森林所有者から経営管理の委託（経営管理権の設定）を受け、林業経営に適した森林を地域の林業経営者に再委託（経営管理実施権の設定）するとともに、林業経営に適さない森林については、市町村が公的に管理（市町村森林経営管理事業）を行う、森林経営管理制度が措置された。"
    },
