      "エ": "2011年の森林法改正で、従来の森林施業計画に代わり森林経営計画の制度が設けられた。まとまりのある森林を対象に計画的な施業と保護を進める。",
      "オ": "森林経営管理制度では、所有者から市町村が管理を引き受けることができる。林業経営に適する森林の管理を林業経営者に委ね、適さないものは市町村自ら管理する仕組みである。"
