    "question": "植生遷移や森林の更新に関する記述A～Dのうち、妥当なもののみを全て挙げているのはどれか。\n\nA. 土壌と植物の繁殖源が存在しない状態から始まる遷移を、一次遷移と呼ぶ。一次遷移の一つである乾性遷移では、乾燥や貧栄養に強いコケや地衣類などが生育を開始してから、長い年月をかけて極相に至る。極相の森林に至るまで1000年近い年月がかかったと推定される場合もある。\nB. 一次遷移の初期に、林道の敷設など人為的な影響を受けた遷移を、二次遷移と呼ぶ。二次遷移は一次遷移より遅く進行する。二次遷移により成立し、極相に至っていない森林を二次林と呼び、人工林も二次林に含まれる。\nC. 遷移の初期に現れる樹種を先駆種と呼び、遷移の後期に現れる樹種を極相種と呼ぶ。一般に、先駆種は極相種に比べ、種子が大きい、成長が速い、寿命が短い、などといった特徴を持つ。先駆種として、アカメガシワやスダジイなどが知られている。\nD. 樹木の寿命だけではなく、病害虫や強風などによる枯死や人為的な伐採による部分的な森林の破壊により、林冠に孔が開いた空間をギャップと呼ぶ。ギャップでは二次遷移が進行する。極相林でも常にどこかでギャップが形成され、様々な発達段階の樹木がモザイク状に分布している。",
