    "difficulty": 3,
    "question": "我が国の立木評価に関する記述A～Dのうち、妥当なもののみを挙げているのはどれか。\n\nA. 費用価法とは、人工林の壮齢林を対象とし、造林に要した費用の合計額である造林費用価を立木の評価額とする方法である。この方法では、林業利率を使わず、高齢級の立木の評価にも使用されることがある。\nB. 期望価法とは、10年生以下の人工林の立木で市場価格のないものを対象とし、これを伐期まで育成したとして、予測される主伐収益と間伐収益を合計した額を、立木の評価額とする方法である。主伐までの間に必要な経費は予測が不確実であるため、考慮しない。\nC. グラーゼル（Glaser）法とは、幼齢林の立木の評価額と伐期における主伐収益とを滑らかな曲線で結び、幼齢林から伐期以前の壮齢林の立木の評価額を求める方法である。この方法では、林業利率などを考慮せず、立木の評価額を概算する上で用いられる。\nD. 市場価逆算法とは、市場価格のある立木を対象として、最寄りの市場で取り引きされる市場価格から、伐採・搬出・運搬・販売に要する全ての事業費及び伐出事業利益を控除して、立木の評価額を算出する一般的な方法である。",
