    "difficulty": 3,
    "question": "次は、水文解析に関する記述であるが、A～Eに当てはまるものの組合せとして最も妥当なのはどれか。\n\n雨水は、様々なプロセスを経て斜面から流出する。流量を時系列的に示した図はハイドログラフと呼ばれ、降雨強度を時系列的に示した図はハイエトグラフと呼ばれる。ハイドログラフは、その形状に基づいて［A］と［B］に分離される。［A］は、河道に降った雨と、斜面からの表面流出及び中間流出で構成され、降雨に伴って速やかに増加し、洪水流出波形の主要部を形成する。降雨イベントごとの総降雨量に対する総直接流出量の割合は、総降雨量が多くなるほど［C］する傾向がある。洪水流出を解析する場合、降雨量のうち、直接流出を形成する成分は［D］と呼ばれる。\n\nハイエトグラフに基づきハイドログラフを算出することを流出解析と呼び、様々な方法が提示されている。［E］は、洪水到達時間内の平均降雨強度からハイドログラフのピークを算出するものであり、砂防堰堤の水通しなどの設計の際に、設計流量の設定に用いられる。",
