    "difficulty": 3,
    "question": "図のように、直角に曲がった細い円管の一端を水の流れと平行に置き、その先端を上流側へ、もう一方の先端を鉛直上方へ向けると、管内外の水位差 H は0.1 mとなった。このときの管外の水流の速度として最も妥当なのはどれか。\n\nただし、管路を流れる水は、ベルヌーイの定理が成り立ち、エネルギー損失（損失水頭）がない完全流体とする。また、重力加速度の大きさを10 m/s²とする。",
