    "question": "河川構造物に関する記述A～Dのうち、妥当なもののみを挙げているのはどれか。\n\nA. 霞堤は、堤防のある区間に開口部を設け、上流側の堤防と下流側の堤防が二重になるようにした不連続な堤防であり、洪水時のピーク流量を低減するために設ける。洪水時には、開口部から堤内地側に水が逆流して下流に流れる洪水流量を減少させ、洪水が終わると、堤内地に氾濫した水を河道内へ排水する機能を有する。\nB. 樋門及び樋管は、堤内地の雨水等が河川や水路を流れ、本川に合流する場合において、洪水等によって本川水位が高くなった際に、河川から堤内地側へ逆流しないように設ける施設である。樋門及び樋管による自然排水が困難な場合には、排水機場を設置してポンプ排水する。\nC. 床止め工は、河床を安定させ、河川の縦断又は横断形状を維持するために設けられる施設である。落差があるものを落差工という。落差工は高さが高いほど設置数を減らすことができ、経済的であるため、その高さは2 m以上を基本とする。落差工の下流側に設置する水叩き工の長さは、流水阻害を避けるため、極力短く設計する。\nD. 遊水地は、河道の一部に拡幅部を設けることで、平時より流水を導流して、減速・貯留するために設けられた施設である。流水による洗掘を防止するために、遊水地内はコンクリートによる三面張り構造を基本とし、常時流水があるため、遊水地内は農地などに利用しない。",
