      "ア": "山地河川における土砂移動現象の形態は、河道の勾配に左右されない。そのため、山地河川を対象として河床変動計算を実施する際には、緩勾配区間と急勾配区間が混在していたとしても、計算対象とする河道の全区間において、流砂量式を用いることができる。",
