      "エ": "掃流砂は河床付近を転がったり跳ねたりして移動する。音響式掃流砂量計の一例は、移動粒子が設置したパイプに衝突したときに生じる音を用いる。",
      "オ": "浮遊砂は採水器などで直接採取できる。濁度から濃度を推定する場合は観測地点での採水データとの関係などを用いて校正する。"
