      "イ": "生物圏保存地域（ユネスコエコパーク）とは、自然の恵みを守り、合理的かつ持続可能に利用するユネスコの事業の一つである。同地域は、核心地域・緩衝地域の二つの地域で構成するとされている。このうち、核心地域は、人と自然が調和した持続可能な発展を実践する地域である。",
