      "ウ": "鳥獣保護区は、鳥獣の保護の見地から、鳥獣保護管理法に基づき、都道府県知事又は市町村長によって指定される。鳥獣保護区内においては、原則として狩猟が禁止されているが、農林水産業や生態系に被害を及ぼすニホンジカ、イノシシなどの狩猟鳥獣については、狩猟による捕獲が認められている。",
