    "session": "senmon-shinrin-shizen",
    "qNumber": 85,
    "type": "multiple-choice",
    "category": "造園計画（自然公園）",
    "topicTags": [
      "外来種の定義・外来生物法・ヒアリ",
      "選択問題"
    ],
    "difficulty": 3,
    "question": "外来種問題に関する記述A～Dのうち、妥当なもののみを挙げているのはどれか。\n\nA. 外来種とは、人によって本来の生息・生育地からそれ以外の地域に持ち込まれた生物のことである。全ての外来種は、生物種や持ち込まれた先の環境にかかわらず、持ち込まれた地域の生態系などに被害を及ぼすことから、外来生物法*1では、我が国の在来種ではない生物は、全て輸入することを禁止している。\nB. 我が国の在来種であっても、本来の生息・生育地以外の地域に持ち込まれたものは、生態系などへの悪影響を及ぼすなど「国内由来の外来種」として問題になるものがある。外来生物法では在来種の国内移動は禁止していないが、環境省・農林水産省が作成した「生態系被害防止外来種リスト*2」には「国内由来の外来種」も掲載されている。\nC. 南米原産のヒアリは、輸入品などに付着して非意図的に生息地以外の地域に持ち込まれ、2000年代以降、中国や台湾などアジア地域にもその生息地を拡大している。ヒアリは、我が国でも国際貨物が到着する港湾地域だけでなく、内陸部でも発見されていることから、その対策強化が令和4（2022）年の外来生物法の改正内容の一つとして盛り込まれた。\nD. 我が国原産の生物が海外で定着して外来種問題を引き起こしている事例に、北アメリカに定着したマメコガネやホテイアオイがあり、これらはIUCN（国際自然保護連合）が作成している世界の侵略的外来種ワースト100にも掲載されている。我が国では、外来生物法に基づき、こうした海外で問題となる在来種を指定し、それらの輸出を原則として禁止している。\n\n*1 特定外来生物による生態系等に係る被害の防止に関する法律\n*2 我が国の生態系等に被害を及ぼすおそれのある外来種リスト",
