    "question": "我が国における歴史・文化を活かしたまちづくりの法制度に関する記述として最も妥当なのはどれか。\n\n*1 古都における歴史的風土の保存に関する特別措置法\n*2 地域における歴史的風致の維持及び向上に関する法律",
