    "difficulty": 3,
    "question": "国が策定する緑の基本方針*1（令和6（2024）年策定）とそれに関連した施策に関する記述A～Dのうち、妥当なもののみを挙げているのはどれか。\n\nA. 緑の基本方針では、将来的な都市のあるべき姿を「人と自然が共生し、環境への負荷が小さく、Well-beingが実感できる緑豊かな都市」と定めている。その実現に向け、都市の緑地を、郊外部も含めて保全・創出し、そのうち市街地については、緑被率が3割以上となることを目指すとしている。\nB. 都市の緑地は、地域固有の生態系を支える基盤であり、また、都市の住民がその生態系を学び、保全などに関わることのできる身近な場所でもある。ネイチャーポジティブの実現に向けて、令和6年の都市緑地法の改正により、目的規定に生物多様性の確保が盛り込まれたほか、緑の基本計画の策定に当たり、生物多様性地域戦略*2との整合が義務付けられた。\nC. 都市の緑地は、地震などによる火災時の延焼を防ぎ、避難地・避難路などとなることに加え、雨水の貯留・浸透による浸水被害の軽減など気候変動影響への緩和策としての機能を有する。令和3（2021）年に水循環基本法の改正と併せて都市緑地法が改正され、特別緑地保全地区の指定要件として、新たに避難地帯を有するものであることが追加された。\nD. 良質な緑地への民間投資を促進する環境整備として、民間企業による良質な緑地確保の取組の価値を適切に評価し、投資を誘導していくことが必要である。令和6年の都市緑地法の改正により、企業などによる良質な緑地確保の取組を、国土交通大臣が評価・認定する仕組みとして、優良緑地確保計画認定制度が創設された。\n\n*1 都市における緑地の保全及び緑化の推進に関する基本的な方針\n*2 生物多様性基本法（平成20年法律第58号）第13条第1項に基づく都道府県又は市区町村の区域内における生物の多様性の保全及び持続可能な利用に関する基本的な計画",
