      "エ": "木材中の音波の伝搬速度（音速）は、音が伝わる方向の弾性率の平方根に比例するため、繊維直交方向よりも繊維方向の方が大きい。また、音速は密度の平方根に反比例するため、密度の低さに比べて弾性率が高い木材の繊維方向の音速は3,000～6,000 m/sの値を示し、鉄やアルミニウムと同程度となる。",
      "オ": "木材の誘電率は含水率が高くなると大きくなる。静電容量式の含水率計は、この性質を利用したものだが、密度が高い木材の方が誘電率は低くなるため補正が必要となる。繊維飽和点より含水率が高くなると、含水率の増加に対する誘電率の増加の度合いが小さくなるため、静電容量式の含水率計は、同点以下の範囲での測定に適している。"
