      "イ": "インサイジングは木材の表面に刃などで一定の間隔の切込みを作り、薬剤の浸透を助ける処理である。強度への影響をすべて一律に1割と定める説明は誤り。",
      "ウ": "加圧処理は容器内の薬液を加圧して材に浸透させる。リューピング法では先に材へ圧縮空気を入れる一方、ローリー法ではこの予備加圧を行わない。",
