      "イ": "ひき板などの厚みのある材料に難燃薬剤水溶液を含浸させる方法としては、常圧下で薬剤に浸した後に加熱と冷却を交互に繰り返すベセル法（ベゼル法）が一般的である。リン酸系の難燃薬剤は、加熱によってガラス状になり、これが木材表面や細胞間隙を塞ぐことで、燃焼を阻害する。",
