      "イ": "合板は、単板を繊維方向が互いに直交するように積層接着した製品である。狂い、反り、割れなどが起こりにくく、強度も安定しており、また、大きな面材を生産できることから、住宅の壁、床、屋根の下地材やフロア台板、コンクリート型枠など、多様な用途に利用される。",
      "ウ": "OSB（配向性ストランドボード）は、丸太から帯鋸を用いてストランドを製造し、その繊維方向の向きをそろえ、平行に積層して製造した木質ボードである。その曲げ強度に関しては、構造用合板に近い強度性能を示す。",
      "エ": "PB（パーティクルボード）は、細かく切削した木材小片に接着剤を添加して熱圧した木質ボードである。水を媒体とした湿式法、又は乾燥状態で接着剤を添加する乾式法によって製造される。日本農林規格（JAS）では、素地PB、単板張りPB、化粧PB、構造用PBが規定されている。",
