    "question": "次は、パルプの特徴とその製造に関する記述であるが、A～Dに当てはまるものの組合せとして最も妥当なのはどれか。\n\n我が国における製紙用のパルプ原料には、木材パルプ、古紙パルプ、非木材パルプがあり、令和5（2023）年における製紙原料消費量のうち、木材パルプを原料としているものは［A］割となっている。木材パルプは、製造方法によって機械パルプ、化学パルプ及び半化学パルプに大別される。機械パルプ化法は、機械的に木部繊維をほぐして取り出す方法で、原料の樹種としては［B］が用いられる場合が多い。一方で、化学パルプ化法は、化学的にリグニンを溶解させてセルロース繊維を取り出す方法で、針葉樹材及び広葉樹材が用いられる。機械パルプ化法と化学パルプ化法を比較すると、［C］は、原料に対する歩留まり（パルプ化収率）は高いが、繊維長が短くなるために紙の力学的強度は低くなる。化学パルプの一つであるクラフトパルプは、［D］と水酸化ナトリウムを薬品として用いたクラフト蒸解によって製造され、廃液中のリグニンなどのエネルギー利用が可能であることから、近年、化学パルプの主流となっている。",
